--- isolated breathing ---
<template>
  <div class="page breathing-page breathing-page-{{ screenSize }} breathing-page-{{ screenViewport }}">
    <text class="session-label">稳态训练</text>
    <text class="remaining">{{ remainingText }}</text>

    <div class="orb-shell orb-shell-{{ screenSize }} orb-shell-{{ screenViewport }}">
      <div class="breath-halo breath-halo-{{ screenViewport }} {{ breathPhase }}">
        <div class="breath-orb breath-orb-{{ screenViewport }} {{ breathPhase }}">
          <div class="orb-core {{ breathPhase }}-core"></div>
        </div>
      </div>
    </div>

    <text class="phase-label phase-label-{{ screenViewport }}">{{ phaseLabel }}</text>
    <text class="pattern-label">{{ patternLabel }}</text>
    <div class="stop-button stop-button-{{ screenViewport }}" onclick="stopTraining">
      <text class="stop-text">结束训练</text>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    screenSize: { type: String, default: 'regular' },
    screenViewport: { type: String, default: 'normal' },
    remainingText: { type: String, default: '60' },
    breathPhase: { type: String, default: 'inhale' },
    phaseLabel: { type: String, default: '慢慢吸气' },
    patternLabel: { type: String, default: '标准节奏 · 4-2-4' },
  },
  stopTraining() { this.$emit('stopTraining'); },
};
</script>

<style>
.page {
  width: 100%;
  height: 100%;
  flex-direction: column;
  align-items: center;
}

.breathing-page {
  padding-top: 28px;
}

.session-label {
  font-size: 13px;
  letter-spacing: 2px;
  color: #76998d;
}

.remaining {
  margin-top: 1px;
  font-size: 30px;
  font-weight: 700;
  color: #f3f6f5;
}

.orb-shell {
  width: 250px;
  height: 250px;
  margin-top: 8px;
  border-width: 1px;
  border-color: #173d33;
  border-radius: 125px;
  justify-content: center;
  align-items: center;
  background-color: #091b17;
}

.breath-halo {
  border-width: 1px;
  border-color: #2b6c58;
  border-radius: 110px;
  justify-content: center;
  align-items: center;
  background-color: #0f2c24;
  transition-property: width, height, opacity, background-color;
  transition-duration: 3600ms;
  transition-timing-function: ease-in-out;
}

.breath-halo.inhale {
  width: 220px;
  height: 220px;
}

.breath-halo.hold {
  width: 208px;
  height: 208px;
  border-color: #66cdb1;
  transition-duration: 1200ms;
}

.breath-halo.exhale {
  width: 154px;
  height: 154px;
}

.breath-orb {
  border-radius: 100px;
  justify-content: center;
  align-items: center;
  background-color: #285f4d;
  transition-property: width, height, opacity, background-color;
  transition-duration: 3600ms;
  transition-timing-function: ease-in-out;
}

.breath-orb.inhale {
  width: 184px;
  height: 184px;
  background-color: #1c5e4a;
}

.breath-orb.hold {
  width: 174px;
  height: 174px;
  background-color: #28725b;
  transition-duration: 1200ms;
}

.breath-orb.exhale {
  width: 120px;
  height: 120px;
  background-color: #164636;
}

.orb-core {
  width: 38px;
  height: 38px;
  border-radius: 19px;
  background-color: #c8f5e8;
  transition-property: transform, opacity, background-color;
  transition-duration: 1200ms;
  transition-timing-function: ease-in-out;
}

.inhale-core {
  opacity: 1;
  transform: scale(1.12);
  animation-name: core-breathe;
  animation-duration: 3600ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
}

.hold-core {
  opacity: 0.88;
  transform: scale(1);
  animation-name: core-hover;
  animation-duration: 1200ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
  animation-direction: alternate;
}

.exhale-core {
  opacity: 0.68;
  transform: scale(0.78);
  animation-name: core-release;
  animation-duration: 3600ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
}

@keyframes core-breathe {
  0% { opacity: 0.62; transform: scale(0.78); }
  100% { opacity: 1; transform: scale(1.12); }
}

@keyframes core-hover {
  0% { opacity: 0.78; transform: scale(0.96); }
  100% { opacity: 0.94; transform: scale(1.04); }
}

@keyframes core-release {
  0% { opacity: 1; transform: scale(1.12); }
  100% { opacity: 0.68; transform: scale(0.78); }
}

.phase-label {
  margin-top: 10px;
  font-size: 27px;
  font-weight: 600;
  color: #ffffff;
}

.pattern-label {
  margin-top: 2px;
  font-size: 13px;
  color: #75968b;
}

.stop-button {
  width: 150px;
  height: 42px;
  margin-top: 12px;
  border-width: 1px;
  border-color: #315347;
  border-radius: 21px;
  justify-content: center;
  align-items: center;
}

.stop-text {
  font-size: 14px;
  color: #9aafa8;
}

/* 小尺寸设备优先保证操作区和底部按钮完整可见。 */
.breathing-page-compact {
  padding-top: 20px;
}

.orb-shell-compact {
  width: 230px;
  height: 230px;
  border-radius: 115px;
}

/* 短视口压缩纵向节奏，确保圆屏主操作始终可见。 */
.breathing-page-short {
  padding-top: 8px;
}

.orb-shell-short {
  width: 130px;
  height: 130px;
  margin-top: 2px;
  border-radius: 65px;
}

.breath-halo-short.inhale,
.breath-halo-short.hold {
  width: 116px;
  height: 116px;
}

.breath-halo-short.exhale {
  width: 86px;
  height: 86px;
}

.breath-orb-short.inhale,
.breath-orb-short.hold {
  width: 108px;
  height: 108px;
}

.breath-orb-short.exhale {
  width: 76px;
  height: 76px;
}

.phase-label-short {
  margin-top: 2px;
  font-size: 26px;
}

.stop-button-short {
  height: 32px;
  margin-top: 4px;
}
</style>
